ikus','Lagoon'=>'Lagúna','Ink'=>'Tintafekete','Orchid'=>'Orchidea','Cobalt'=>'Kobalt','Stone'=>'Kő','Facebook Classic'=>'Facebook klasszikus','Twitter Classic'=>'Twitter klasszikus','Twitter Modern'=>'Twitter modern','Main Admin Color settings'=>'Elsődleges admin színbeállítások','Main Admin Color'=>'Elsődleges admin szín','Primary brand color'=>'Elsődleges márkaszín','Text Color'=>'Szövegszín','Primary text color'=>'Elsődleges szövegszín','Highlight Color'=>'Kiemelő szín','Used for hovers and highlights'=>'Használva lebegéshez és kiemelésekhez','Notification Color'=>'Értesítési szín','Used for alerts and notifications'=>'Használva figyelmeztetésekhez és értesítésekhez','Background Color'=>'Háttérszín','Page background color'=>'Oldal háttérszíne','Link element colors'=>'Link elem színei','Default Link Color'=>'Alapértelmezett link szín','Standard link color'=>'Szabványos link szín','Link Hover Color'=>'Link lebegő szín','Color on hover'=>'Szín lebegéskor','Delete Link Color'=>'Link törlés szín','Color for delete/trash actions'=>'Szín törlés/kuka műveletekhez','Trash Link Color'=>'Kuka link szín','Color for trash actions'=>'Szín kuka műveletekhez','Spam Link Color'=>'Spam link szín','Color for spam actions'=>'Szín spam műveletekhez','Inactive Link Color'=>'Inaktív link szín','Color for inactive items'=>'Szín inaktív elemekhez','Tables'=>'Táblázatok','Table element colors'=>'Táblázat elem színei','Table Header Background'=>'Táblázat fejléc háttér','Table Header Text'=>'Táblázat fejléc szöveg','Table Row Background'=>'Táblázat sor háttér','Table Row Text Color'=>'Táblázat sor szöveg színe','Row Hover Background'=>'Sor lebegő háttér','Table Border Color'=>'Táblázat szegély színe','Alternate Row Background'=>'Felváltott sor háttér','Alternate Row Text Color'=>'Felváltott sor szöveg színe','Forms'=>'Űrlapok','Form input colors'=>'Űrlap bevitel színei','Input Border Color'=>'Bevitel szegély színe','Input Focus Border'=>'Bevitel fókusz szegély','Input Background Color'=>'Be